import type { VariableConfig } from '../../Variable'

/**
 * Configuration type for email variables
 */
export type EmailVariableType<Type extends string = string> = VariableConfig<Type>

/**
 * A Variable for an email field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the email variable including:
 *   * **question** - Question text displayed to the user
 *   * **exampleText**? - Example text for the variable
 *   * **defaultValue**? - Default value for the variable
 *   * And all other properties from the base Variable type
 */
export function EmailVariable(config: EmailVariableType) {
    return config
}
